"""Saved bounded follow-ups; run acquisition recipes from recipes.json for reproduction."""
import json,sys,re,urllib.parse
from acquire import fetch,read,links,MAN,ROOT
urls=[('arcgis-kansas-precinct-search','https://www.arcgis.com/sharing/rest/search?'+urllib.parse.urlencode({'q':'precinct Kansas','num':100,'f':'json'}),'dasc-hub'),('shawnee-webmap','https://www.arcgis.com/sharing/rest/content/items/31d5bdbf62124086944881ed1bbcbd31/data?f=json','shawnee-config'),('crawford-webmap','https://www.arcgis.com/sharing/rest/content/items/a6ce3f5efe064715bb32776250d5e06c/data?f=json','crawford-app'),('franklin-webmap','https://www.arcgis.com/sharing/rest/content/items/e27436f55cd3472791629a7a6deb1890/data?f=json','franklin-app'),('saline-webmap','https://www.arcgis.com/sharing/rest/content/items/c18b83195d404a739255cca6ea884ce5/data?f=json','saline-app'),('butler-app','https://www.arcgis.com/sharing/rest/content/items/dfd7607bb22a472a892d911dd9fa4e1d/data?f=json','butler-hub'),('lyon-city-pdf','https://www.lyoncountyks.gov/DocumentCenter/View/2384/City-of-Emporia-Polling-Sites-and-Voting-Precincts-PDF---Updated-10526','lyon-election'),('lyon-rural-pdf','https://www.lyoncountyks.gov/DocumentCenter/View/2262/Rural-Area-Voting-Precincts-and-Polling-Sites-PDF---Updated-426','lyon-election'),('lyon-notice-pdf','https://www.lyoncountyks.gov/DocumentCenter/View/2386/Precincts-1-2-7-and-8---Notice-of-Change-of-Polling-Place-PDF','lyon-election'),('finney-city-pdf','https://finneycountyks.gov/DocumentCenter/View/7252/Voting-Districts-and-Locations---City','finney-poll'),('finney-county-pdf','https://finneycountyks.gov/DocumentCenter/View/7253/Voting-Districts-and-Locations---County','finney-poll'),('finney-hub','https://votinghub-finneycountygis.hub.arcgis.com/','finney-poll'),('barton-county-pdf','https://www.bartoncounty.org/vimages/shared/vnews/stories/5171595615619/BTCOKSvotingLocationsJune2022.pdf','barton-maps'),('barton-city-pdf','https://www.bartoncounty.org/vimages/shared/vnews/stories/5171595615619/GrBndPrecWardMap2023VoteLocJune2024.pdf','barton-maps'),('barton-hoisington-pdf','https://www.bartoncounty.org/vimages/shared/vnews/stories/5171595615619/HoisingtonVoteWards.pdf','barton-maps'),('pott-districts','https://www.pottcounty.org/177/District-Maps','pott-gis'),('pott-app','https://www.arcgis.com/sharing/rest/content/items/d40d678dec6f4ed2b66f83b06609b228/data?f=json','pott-gis'),('cowley-election','https://www.cowleycountyks.gov/202/Election-Services','cowley-sitemap'),('cowley-gis','https://www.cowleycountyks.gov/374/GIS-Services','cowley-sitemap'),('montgomery-maps','https://www.mgcountyks.org/282/County-Maps','montgomery-home'),('montgomery-election','https://www.mgcountyks.org/197/Voting-Elections','montgomery-home'),('sumner-home','https://www.co.sumner.ks.us/',None),('leavenworth-home','https://www.leavenworthcounty.gov/',None),('reno-alt','https://renocountyks.gov/gis/',None),('reno-service','https://services6.arcgis.com/Z4v2bMJenWjCbO4R/arcgis/rest/services/Reno_County_Commission_Districts_WFL1/FeatureServer?f=json',None)]
for k,u,p in urls:
 r,b=fetch(k,u,p,'Bounded alternative or county-linked original/config')
 if r.get('status')==200 and not b.startswith(b'%PDF'):
  if b[:1] in (b'{',b'['):
   try:j=json.loads(b)
   except Exception:continue
   if 'results'in j: print(k,[(x['id'],x['title'],x['owner'],x.get('url')) for x in j['results']],flush=True)
   else:
    s=json.dumps(j);print(k,re.findall(r'.{0,70}(?:webmap|itemId|FeatureServer|MapServer|[Pp]recinct|layers).{0,140}',s)[:25],flush=True)
  else:
   a=links(k);print(k,[(x['text'][:65],x['url']) for x in a if any(t in (x['text']+' '+x['url']).lower() for t in ['precinct','arcgis','gis','vot','map','elect'])][:35],flush=True)
